  /* ------------------------------------------------------------------ */
  /* 3. Body shell — lofted cross-sections, closed front & rear faces    */
  /* ------------------------------------------------------------------ */
  const FRONT_AXLE = 1.44;
  const REAR_AXLE = -1.32;
  const WHEEL_R = 0.335;
  const ARCH_R = 0.44;
  const HALF_W = 0.865;
  const X_FRONT = 2.34;
  const X_REAR = -2.30;

  const TOP_KEYS = [
    [-2.30, 0.93], [-2.24, 0.925], [-2.10, 0.918], [-1.55, 0.918],
    [-1.02, 0.890], [0.95, 0.862], [1.55, 0.848], [1.98, 0.826],
    [2.16, 0.806], [2.26, 0.790], [2.32, 0.772], [2.34, 0.700],
  ];
  const WIDTH_KEYS = [
    [-2.30, 0.815], [-2.24, 0.850], [-2.05, 0.862], [-1.20, 0.865],
    [1.20, 0.865], [2.05, 0.860], [2.20, 0.848], [2.28, 0.812],
    [2.33, 0.760], [2.34, 0.700],
  ];
  const BOTTOM_KEYS = [
    [-2.30, 0.255], [-2.05, 0.250], [0.90, 0.246], [1.98, 0.250], [2.30, 0.255], [2.34, 0.262],
  ];

  function sampleKeys(keys, x) {
    if (x <= keys[0][0]) return keys[0][1];
    const last = keys[keys.length - 1];
    if (x >= last[0]) return last[1];
    for (let i = 0; i < keys.length - 1; i++) {
      const [x0, v0] = keys[i], [x1, v1] = keys[i + 1];
      if (x >= x0 && x <= x1) {
        const u = smooth((x - x0) / (x1 - x0));
        return v0 + (v1 - v0) * u;
      }
    }
    return last[1];
  }

  const topAt = x => sampleKeys(TOP_KEYS, x);
  const widthAt = x => sampleKeys(WIDTH_KEYS, x);
  const ARCH_BLEND = ARCH_R + 0.10; // arch cut eases into the sill line
  const bottomAt = x => {
    let y = sampleKeys(BOTTOM_KEYS, x);
    for (const ax of [FRONT_AXLE, REAR_AXLE]) {
      const dx = Math.abs(x - ax);
      if (dx < ARCH_BLEND) {
        const dxc = Math.min(dx, ARCH_R);
        const archY = WHEEL_R + Math.sqrt(ARCH_R * ARCH_R - dxc * dxc) + 0.006;
        // smooth shoulder at the arch ends — no abrupt vertical notch
        const w = dx <= ARCH_R ? 1 : 1 - smooth((dx - ARCH_R) / (ARCH_BLEND - ARCH_R));
        y = Math.max(y, y + (archY - y) * w);
      }
    }
    return y;
  };

  // lateral surface position at (x,y) — used to place side details
  const sideZ = (x, y) => {
    const w = widthAt(x);
    const y1 = topAt(x);
    const y0 = Math.min(bottomAt(x), y1 - 0.06);
    const t = clamp01((y - (y0 + 0.12)) / Math.max(0.001, y1 - 0.12 - (y0 + 0.12)));
    return w * (1 - 0.05 * t * t) * 0.998;
  };

  function halfSection(x) {
    const w = widthAt(x);
    const y1 = topAt(x);
    const y0 = Math.min(bottomAt(x), y1 - 0.055);
    const wTop = w * 0.80;
    const pts = [];
    const push = (z, y) => pts.push([Math.max(0, z), Math.min(y, y1)]);

    for (let i = 0; i <= 3; i++) push(w * 0.78 * (i / 3), y0);
    const rc = Math.min(0.13, (y1 - y0) * 0.3);
    for (let i = 1; i <= 5; i++) {
      const a = (Math.PI / 2) * (i / 5);
      push(w * 0.78 + (w - w * 0.78) * Math.sin(a), y0 + rc - rc * Math.cos(a));
    }
    const ySide0 = y0 + rc;
    const ySide1 = y1 - Math.min(0.13, (y1 - y0) * 0.32);
    for (let i = 1; i <= 12; i++) {
      const t = i / 12;
      push(w * (1 - 0.05 * t * t), ySide0 + (ySide1 - ySide0) * t);
    }
    const p0 = [w * 0.95, ySide1], p1 = [wTop + 0.045, ySide1 + 0.025], p2 = [wTop, y1];
    for (let i = 1; i <= 6; i++) {
      const t = i / 6, mt = 1 - t;
      push(mt * mt * p0[0] + 2 * mt * t * p1[0] + t * t * p2[0],
           mt * mt * p0[1] + 2 * mt * t * p1[1] + t * t * p2[1]);
    }
    for (let i = 1; i <= 6; i++) {
      const t = i / 6;
      push(wTop * (1 - t), y1 + 0.005 * Math.sin(Math.PI * t * 0.5));
    }
    return pts;
  }

  const ringAt = (x) => {
    const half = halfSection(x);
    const ring = [];
    for (let j = 0; j < half.length; j++) ring.push([x, half[j][1], half[j][0]]);
    for (let j = half.length - 2; j >= 1; j--) ring.push([x, half[j][1], -half[j][0]]);
    return ring;
  };

  {
    const NX = 150;
    const rings = [];
    for (let i = 0; i <= NX; i++) rings.push(ringAt(X_FRONT - (X_FRONT - X_REAR) * i / NX));
    const M = rings[0].length;
    const posArr = [];
    for (const ring of rings) for (const p of ring) posArr.push(p[0], p[1], p[2]);
    const idx = [];
    for (let i = 0; i < NX; i++) {
      for (let j = 0; j < M; j++) {
        const a = i * M + j, b = i * M + ((j + 1) % M);
        const c = (i + 1) * M + j, d = (i + 1) * M + ((j + 1) % M);
        idx.push(a, b, c, b, d, c);
      }
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(posArr, 3));
    g.setIndex(idx);
    g.computeVertexNormals();
    const body = new THREE.Mesh(g, paintMat);
    body.name = 'BodyShell';
    body.castShadow = true;
    body.receiveShadow = true;
    root.add(body);

    // closed front & rear faces (fans)
    for (const [xFace, sign] of [[X_FRONT, 1], [X_REAR, -1]]) {
      const ring = ringAt(xFace);
      const cx = xFace;
      const cy = ring.reduce((s, p) => s + p[1], 0) / ring.length;
      const posF = [cx, cy, 0];
      const indexF = [];
      for (const p of ring) posF.push(p[0], p[1], p[2]);
      for (let j = 1; j <= ring.length; j++) {
        indexF.push(0, j, j % ring.length + 1);
      }
      const gf = new THREE.BufferGeometry();
      gf.setAttribute('position', new THREE.Float32BufferAttribute(posF, 3));
      gf.setIndex(indexF);
      gf.computeVertexNormals();
      const cap = new THREE.Mesh(gf, paintCapMat);
      cap.castShadow = true;
      cap.receiveShadow = true;
      root.add(cap);
    }
  }

  // Underbody trays — three segments that stop short of each arch opening,
  // so nothing cuts across the wheels
  cbox(1.80, 0.10, 1.50, matteBlackMat, root, 0.06, 0.215, 0);
  cbox(0.36, 0.10, 1.50, matteBlackMat, root, 2.10, 0.215, 0);
  cbox(0.42, 0.10, 1.50, matteBlackMat, root, -2.01, 0.215, 0);
  // Rocker sills only between the arches — clear of both tyres
  for (const side of [-1, 1]) {
    rbox(1.72, 0.07, 0.05, 0.02, trimBlackMat, root, 0.06, 0.262, side * 0.845);
  }

  /* ------------------------------------------------------------------ */
  /* 4. Front fascia, grille & headlights                               */
  /* ------------------------------------------------------------------ */
  const frontGroup = new THREE.Group();
  root.add(frontGroup);
  const XF = X_FRONT + 0.012;   // face plane for add-on parts

  // Upper grille (gloss black) + chrome bar + Honda badge
  rbox(0.05, 0.105, 0.74, 0.018, glossBlackMat, frontGroup, XF + 0.01, 0.605, 0);
  for (let i = 0; i < 2; i++) cbox(0.02, 0.010, 0.68, trimBlackMat, frontGroup, XF + 0.032, 0.578 + i * 0.030, 0);
  cbox(0.016, 0.014, 0.80, chromeMat, frontGroup, XF + 0.034, 0.652, 0);
  rbox(0.03, 0.092, 0.108, 0.012, chromeMat, frontGroup, XF + 0.032, 0.605, 0);
  cbox(0.012, 0.058, 0.014, glossBlackMat, frontGroup, XF + 0.048, 0.605, -0.030);
  cbox(0.012, 0.058, 0.014, glossBlackMat, frontGroup, XF + 0.048, 0.605, 0.030);
  cbox(0.012, 0.013, 0.046, glossBlackMat, frontGroup, XF + 0.048, 0.605, 0);

  // Lower intake
  rbox(0.05, 0.135, 0.98, 0.024, glossBlackMat, frontGroup, XF + 0.01, 0.405, 0);
  for (let i = 0; i < 3; i++) cbox(0.02, 0.011, 0.92, trimBlackMat, frontGroup, XF + 0.030, 0.365 + i * 0.036, 0);

  // The registration lettering is actual extruded outline geometry, not a texture.
  function addPlateText(parent, x, y, facing) {
    const text = 'StepTuDeen';
    const width = [...text].reduce((sum, char) => sum + glyphs[char].advance, 0);
    const scale = 0.300 / width;
    const lettering = new THREE.Group();
    lettering.name = facing > 0 ? 'Front_StepTuDeen_3D' : 'Rear_StepTuDeen_3D';
    lettering.position.set(x, y, 0);
    lettering.rotation.y = facing > 0 ? Math.PI / 2 : -Math.PI / 2;
    parent.add(lettering);
    let cursor = -width / 2;
    for (const char of text) {
      const item = glyphs[char], path = new THREE.ShapePath();
      for (const cmd of item.commands) {
        const a = cmd.slice(1).map(v => v * scale);
        if (cmd[0] === 'M') path.moveTo(cursor * scale + a[0], a[1]);
        else if (cmd[0] === 'L') path.lineTo(cursor * scale + a[0], a[1]);
        else if (cmd[0] === 'Q') path.quadraticCurveTo(cursor * scale + a[0], a[1], cursor * scale + a[2], a[3]);
        else if (cmd[0] === 'C') path.bezierCurveTo(cursor * scale + a[0], a[1], cursor * scale + a[2], a[3], cursor * scale + a[4], a[5]);
        else if (cmd[0] === 'Z' && path.currentPath) path.currentPath.closePath();
      }
      const shapes = path.toShapes(false);
      if (shapes.length) {
        const letters = new THREE.Mesh(new THREE.ExtrudeGeometry(shapes, { depth: 0.0015, bevelEnabled: false, curveSegments: 5 }), plateInkMat);
        lettering.add(letters);
      }
      cursor += item.advance;
    }
  }

  // Front plate
  rbox(0.018, 0.10, 0.34, 0.008, plateMat, frontGroup, XF + 0.030, 0.512, 0);
  addPlateText(frontGroup, XF + 0.042, 0.490, 1);

  // Chin spoiler / splitter
